example:
context shop

type Order = { id: String }
actor Shop = Producer where IsContext(shop)

service fulfil from queue("orders") {
  delivery { deadLetter: None }
  on message(order: Order) -> Effect[QueueResult] by Shop {   // ✗ nothing verifies the sender yet
    Ack
  }
}

service fulfil from queue("orders") {
  delivery { deadLetter: None }
  on message(order: Order) -> Effect[QueueResult] by Producer {   // ✓ anyone on the account, said outright
    Ack
  }
}
